  pending:          {hold:'held', cancel:'cancelled', expire:'expired'},
  held:             {startPayment:'awaiting_payment', cancel:'cancelled', expire:'expired'},
  awaiting_payment: {cancel:'cancelled', expire:'expired'},
  paid:             {refund:'refunded'},
  cancelled:{}, expired:{}, refunded:{},
};
const EVENTS = ['hold','startPayment','webhookSucceeded','webhookFailed','cancel','expire','refund'];
const init = () => ({status:'pending', inFlight:false, needsRefund:false, statuses:['pending'], history:[]});

function apply(s, ev, guard) {
  const n = {...s, history:[...s.history, ev]};
  if (ev.startsWith('webhook')) {
    if (!s.inFlight) return null;              // no payment outstanding
    n.inFlight = false;
    if (ev === 'webhookFailed') { if (s.status === 'awaiting_payment') n.status = 'held'; }
    else if (!guard) n.status = 'paid';        // naive: trust the PSP blindly
    else if (s.status === 'awaiting_payment') n.status = 'paid';
    else n.needsRefund = true;                 // money taken, reservation not live
  } else {
    const to = T[s.status][ev];
    if (!to) return null;
    n.status = to;
    if (ev === 'startPayment') n.inFlight = true;  // cancel/expire do NOT clear this
  }
  n.statuses = [...s.statuses, n.status];
  return n;
}

const violates = x => { const i = x.statuses.indexOf('cancelled'); return i >= 0 && x.statuses.indexOf('paid', i) > i; };
const guard = () => document.getElementById('guard').checked;
let s = init();

function render() {
  document.getElementById('buttons').innerHTML = EVENTS.map(e =>
    `<button ${apply(s, e, guard()) ? '' : 'disabled'} onclick="fire('${e}')">${e}</button>`).join('');
  document.getElementById('state').textContent = JSON.stringify(s, null, 2);
  const v = document.getElementById('verdict');
  v.className = violates(s) ? 'bad' : 'ok';
  v.textContent = violates(s) ? 'VIOLATION: reached paid after cancelled'
    : s.needsRefund ? 'No violation, but money was captured on a dead reservation (needsRefund)'
    : 'No cancelled→paid in this history';
}
function fire(e) { const n = apply(s, e, guard()); if (n) { s = n; render(); } return !!n; }
function reset() { s = init(); render(); }
document.getElementById('guard').onchange = render;

const WALKS = {
  'Happy path': [
    ['hold','Seat is held.'],
    ['startPayment','Charge sent to PSP; inFlight = true.'],
    ['webhookSucceeded','PSP confirms → paid.']],
  'Cancel, no payment': [
    ['hold','Seat is held.'],
    ['cancel','Cancelled before paying. Webhook buttons stay disabled: nothing in flight.']],
  'Late webhook (the suspect)': [
    ['hold','Seat is held.'],
    ['startPayment','Charge in flight.'],
    ['cancel','User cancels. Look at state: inFlight is still true. The PSP was never told.'],
    ['webhookSucceeded','Webhook lands after cancel. Guard off → paid (VIOLATION). Guard on → stays cancelled, needsRefund = true.']],
  'Expiry race': [
    ['hold','Seat is held.'],
    ['startPayment','Charge in flight.'],
    ['expire','Hold times out while payment is pending.'],
    ['webhookSucceeded','Same hole via expired. Does the real code handle this path too?']],
  'Failed, then cancel': [
    ['hold','Seat is held.'],
    ['startPayment','Charge in flight.'],
    ['webhookFailed','Payment fails → back to held, inFlight cleared.'],
    ['cancel','Cancel is now safe: no webhook can follow.']],
};
let walk = null, step = 0;
document.getElementById('tabs').innerHTML = Object.keys(WALKS).map(k =>
  `<button onclick="openWalk('${k}')">${k}</button>`).join('');
function openWalk(k) { walk = k; step = 0; reset(); renderWalk(); }
function next() { if (fire(WALKS[walk][step][0])) step++; renderWalk(); }
function renderWalk() {
  document.querySelectorAll('.tabs button').forEach(b => b.classList.toggle('active', b.textContent === walk));
  const steps = WALKS[walk];
  document.getElementById('walk').innerHTML = '<ol>' + steps.map(([e, txt], i) =>
    `<li class="${i < step ? 'done' : i === step ? 'cur' : ''}"><code>${e}</code>: ${txt}</li>`).join('') + '</ol>'
    + `<button onclick="next()" ${step >= steps.length ? 'disabled' : ''}>Next step</button>`;
}

function search() {
  const g = guard(); let q = [init()], found = null, refunds = 0, n = 0;
  outer: for (let d = 0; d < 6; d++) {
    const nq = [];
    for (const x of q) for (const e of EVENTS) {
      const y = apply(x, e, g); if (!y) continue; n++;
      if (y.needsRefund && !x.needsRefund) refunds++;
      if (violates(y)) { found = y; break outer; }
      nq.push(y);
    }
    q = nq;
  }
  document.getElementById('search').textContent = found
    ? `Guard ${g ? 'ON' : 'OFF'}: shortest counterexample after ${n} states:\n  ${found.history.join(' → ')}\n  statuses: ${found.statuses.join(' → ')}`
    : `Guard ${g ? 'ON' : 'OFF'}: no cancelled→paid path in ${n} states (depth ≤ 6).\n  Paths ending in needsRefund: ${refunds}`;
}
render();
</script></body></html>
