<h2>Can a reservation reach <code>paid</code> after <code>cancelled</code>?</h2>
<label><input type="checkbox" id="bypass"> Webhook bypasses the state machine
  (handler does <code>status = 'paid'</code> unconditionally)</label>
<div class="tabs" id="tabs"></div>
<div id="panel"></div>
<h3>State</h3><pre id="state"></pre>
<h3>Invariants</h3><div id="inv"></div>
<h3>Log</h3><pre id="log"></pre>
<script>
// ---- EDIT ME: transition table under test ----
const T = {
  draft:            {hold:'held', cancel:'cancelled'},
  held:             {start_payment:'awaiting_payment', cancel:'cancelled', expire:'expired'},
  awaiting_payment: {payment_succeeded:'paid', payment_failed:'held', cancel:'cancelled', expire:'expired'},
  paid:             {cancel:'refunded'},
  cancelled:        {},
  expired:          {},
  refunded:         {},
};
const EVENTS = ['hold','start_payment','cancel','expire','deliver_webhook_success','deliver_webhook_failure'];

let s;
const bypass = () => document.getElementById('bypass').checked;
function reset(){ s = {status:'draft', history:['draft'], inFlight:0, captured:0, log:[]}; render(); }

function fire(ev){
  const from = s.status;
  if (ev.startsWith('deliver_webhook')) {
    if (!s.inFlight) { s.log.push(`${ev}: nothing in flight, ignored`); return render(); }
    s.inFlight--;
    if (ev === 'deliver_webhook_failure') return apply(from, 'payment_failed');
    s.captured++;                       // the provider took the money, whatever our status says
    if (bypass()) return setStatus(from, 'paid', 'payment_succeeded (bypass)');
    return apply(from, 'payment_succeeded');
  }
  if (ev === 'start_payment' && T[from].start_payment) s.inFlight++;
  apply(from, ev);
}
function apply(from, ev){
  const to = T[from][ev];
  if (!to) { s.log.push(`${ev} in ${from}: REJECTED`); return render(); }
  if (from === 'paid' && to === 'refunded') s.captured--;
  setStatus(from, to, ev);
}
function setStatus(from, to, ev){
  s.status = to; s.history.push(to); s.log.push(`${ev}: ${from} → ${to}`); render();
}

function violations(){
  const v = [], h = s.history, c = h.indexOf('cancelled');
  if (c >= 0 && h.indexOf('paid', c) > c) v.push('Reached paid AFTER cancelled');
  if (s.captured > 0 && s.status !== 'paid')
    v.push(`Money captured (${s.captured}) but status is ${s.status}: no refund path`);
  return v;
}
function render(){
  document.getElementById('state').textContent = JSON.stringify({
    status: s.status, inFlightPayments: s.inFlight, capturedPayments: s.captured,
    history: s.history.join(' → ')}, null, 2);
  const v = violations();
  document.getElementById('inv').innerHTML = v.length
    ? v.map(x => `<div class="bad">✗ ${x}</div>`).join('') : '<div class="ok">✓ none violated</div>';
  document.getElementById('log').textContent = s.log.join('\n');
}

const RACE = [['hold','Reserve the slot'],
              ['start_payment','User submits card; provider call is in flight'],
              ['cancel','User cancels while the provider is still processing'],
              ['deliver_webhook_success','Provider success webhook arrives late']];
const WALKS = {
  'Cancel, then pay': {bypass:false,
    steps:[['hold','Reserve the slot'],['cancel','User cancels'],['start_payment','Try to pay a cancelled reservation']],
    verdict:'start_payment is rejected. The table guards the direct path.'},
  'Late webhook (guarded)': {bypass:false, steps:RACE,
    verdict:'Status stays cancelled, but money was captured. The table is "correct" and the customer is still charged.'},
  'Late webhook (naive handler)': {bypass:true, steps:RACE,
    verdict:'cancelled → paid. This is the bug the question is about.'},
  'Expiry + late webhook': {bypass:false,
    steps:[['hold','Reserve'],['start_payment','Pay'],['expire','Hold times out'],['deliver_webhook_success','Webhook arrives']],
    verdict:'Same shape as the race: expired with money captured.'},
};

function reach(){
  const g = {};
  for (const k in T) { g[k] = {...T[k]}; if (bypass()) g[k].payment_succeeded = 'paid'; }
  const prev = {cancelled:null}, q = ['cancelled'];
  while (q.length) { const n = q.shift();
    for (const [ev,to] of Object.entries(g[n])) if (!(to in prev)) { prev[to] = [n,ev]; q.push(to); } }
  let out;
  if (!('paid' in prev)) out = `paid is NOT reachable from cancelled (bypass ${bypass()?'on':'off'}).\nReachable: ${Object.keys(prev).join(', ')}\nNote: this static check cannot see in-flight payments. Run the walkthroughs.`;
  else { const p = []; for (let n='paid'; prev[n]; n = prev[n][0]) p.unshift(`${prev[n][0]} --${prev[n][1]}--> ${n}`);
         out = 'paid IS reachable from cancelled:\n' + p.join('\n'); }
  document.getElementById('reach').textContent = out;
}

function tab(name){
  document.querySelectorAll('#tabs button').forEach(b => b.classList.toggle('on', b.textContent === name));
  const p = document.getElementById('panel');
  if (name === 'Free play') {
    p.innerHTML = EVENTS.map(e => `<button onclick="fire('${e}')">${e}</button>`).join('')
      + ' <button onclick="reset()">reset</button>';
    return reset();
  }
  if (name === 'Reachability') { p.innerHTML = '<pre id="reach"></pre>'; return reach(); }
  const w = WALKS[name]; document.getElementById('bypass').checked = w.bypass; reset(); let i = 0;
  p.innerHTML = '<p id="step"></p><button id="next">Next step</button> <button id="restart">Restart</button>';
  const show = () => document.getElementById('step').textContent = i < w.steps.length
    ? `Step ${i+1}/${w.steps.length}: ${w.steps[i][1]} (fires ${w.steps[i][0]})` : 'Done. ' + w.verdict;
  document.getElementById('next').onclick = () => { if (i < w.steps.length) { fire(w.steps[i][0]); i++; show(); } };
  document.getElementById('restart').onclick = () => { reset(); i = 0; show(); };
  show();
}
document.getElementById('bypass').onchange = () => { if (document.getElementById('reach')) reach(); };
document.getElementById('tabs').innerHTML = ['Free play', ...Object.keys(WALKS), 'Reachability']
  .map(t => `<button onclick="tab('${t}')">${t}</button>`).join('');
tab('Free play');
</script></body></html>
```

## What it shows with the assumed table

| Scenario | Reaches `paid` after `cancelled`? | Money captured while not `paid`? |
|---|---|---|
| Cancel, then pay | No (rejected) | No |
| Late webhook, guarded | No | **Yes** |
| Late webhook, naive handler | **Yes** | No |
| Expiry + late webhook | No | **Yes** |

The likely finding is that the answer depends on the webhook handler, not on the table. If the handler bypasses the machine, `paid` is reachable after `cancelled`. If it goes through the machine, the status stays correct, but the customer can still be charged for a cancelled reservation.

So the real design decision is what `payment_succeeded` should do in `cancelled` and `expired`. One option is to auto-refund. The other is to add an explicit `cancelled → refund_pending` transition. The bad outcome is silently dropping the event.

