<h2>PROTOTYPE — reservation state machine</h2>
<label><input type="checkbox" id="guarded"> Guarded webhook handler</label>
<div id="status"></div><div id="verdict"></div>

<h3>Free play</h3>
<div id="buttons"></div><button onclick="reset()">Reset</button>

<h3>Guided walkthroughs</h3>
<div class="tabs" id="tabs"></div>
<p id="desc"></p><button onclick="step()">Next step ▶</button> <span id="progress"></span>

<h3>History</h3><table id="hist"></table>
<h3>Full state</h3><pre id="dump"></pre>

<script>
const T = {
  requested:       {HOLD:'held', CANCEL:'cancelled'},
  held:            {PAY:'payment_pending', CANCEL:'cancelled', EXPIRE:'expired'},
  payment_pending: {FAIL:'held', CANCEL:'cancelled', EXPIRE:'expired'},
  paid:            {CANCEL:'cancelled', REFUND:'refunded'},
  cancelled:       {REINSTATE:'held'},
  expired:{}, refunded:{}
};
const EVENTS = ['HOLD','PAY','WEBHOOK_OK','FAIL','CANCEL','EXPIRE','REFUND','REINSTATE'];

let S;
function reset(){ S={status:'requested', paymentsStarted:0, refundOwed:false, history:[]}; render(); }

function onWebhook(s){
  if(!document.getElementById('guarded').checked)
    return {to:'paid', note:'naive: handler sets status=paid unconditionally'};
  if(s==='payment_pending') return {to:'paid', note:'capture accepted'};
  if(s==='paid') return {to:'paid', note:'duplicate webhook, idempotent no-op'};
  S.refundOwed=true; return {to:s, note:'late payment on '+s+': stay, flag refund'};
}

function apply(ev){
  const from=S.status; let to=from, note='';
  if(ev==='WEBHOOK_OK'){
    if(!S.paymentsStarted){ note='ignored: no payment ever started'; }
    else ({to,note}=onWebhook(from));
  } else if(T[from][ev]){
    to=T[from][ev];
    if(ev==='PAY') S.paymentsStarted++;
    if(ev==='CANCEL' && from==='paid'){ S.refundOwed=true; note='refund owed'; }
  } else note='ignored: no transition';
  S.status=to; S.history.push({ev,from,to,note}); render();
}

function verdict(){
  let seenCancel=false, reinstated=false;
  for(const h of S.history){
    if(h.to==='cancelled') {seenCancel=true; reinstated=false;}
    if(h.ev==='REINSTATE') reinstated=true;
    if(seenCancel && h.to==='paid' && h.from!=='paid')
      return reinstated
        ? '<div class="warn">paid after cancelled via REINSTATE — is that intended?</div>'
        : '<div class="bad">VIOLATION: paid after cancelled with no reinstate</div>';
  }
  return '<div class="ok">No paid-after-cancelled so far</div>';
}

function render(){
  document.getElementById('status').textContent='Status: '+S.status;
  document.getElementById('verdict').innerHTML=verdict();
  document.getElementById('hist').innerHTML='<tr><th>#</th><th>event</th><th>from</th><th>to</th><th>note</th></tr>'+
    S.history.map((h,i)=>`<tr><td>${i+1}</td><td>${h.ev}</td><td>${h.from}</td><td>${h.to}</td><td>${h.note}</td></tr>`).join('');
  document.getElementById('dump').textContent=JSON.stringify(S,null,2);
}

const WALKS = {
  'Happy path':            {d:'Baseline: hold, pay, webhook arrives.', s:['HOLD','PAY','WEBHOOK_OK']},
  'Cancel during payment': {d:'User cancels while capture is in flight; webhook lands after.', s:['HOLD','PAY','CANCEL','WEBHOOK_OK']},
  'Expire then late pay':  {d:'Hold times out mid-payment; provider confirms late.', s:['HOLD','PAY','EXPIRE','WEBHOOK_OK']},
  'Reinstate':             {d:'Cancelled then reinstated and paid. Legit or not?', s:['HOLD','CANCEL','REINSTATE','PAY','WEBHOOK_OK']},
  'Duplicate after cancel':{d:'Paid, cancelled, then provider retries the old webhook.', s:['HOLD','PAY','WEBHOOK_OK','CANCEL','WEBHOOK_OK']},
};
let cur, idx;
function pick(name){ cur=name; idx=0; reset();
  document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('on',b.textContent===name));
  document.getElementById('desc').textContent=WALKS[name].d; prog(); }
function step(){ const s=WALKS[cur].s; if(idx<s.length){ apply(s[idx++]); prog(); } }
function prog(){ const s=WALKS[cur].s;
  document.getElementById('progress').textContent=`${idx}/${s.length} — next: ${s[idx]||'(done)'}`; }

document.getElementById('buttons').innerHTML=EVENTS.map(e=>`<button onclick="apply('${e}')">${e}</button>`).join('');
document.getElementById('tabs').innerHTML=Object.keys(WALKS).map(n=>`<button onclick="pick('${n}')">${n}</button>`).join('');
document.getElementById('guarded').onchange=()=>pick(cur);
reset(); pick('Happy path');
</script></body></html>
